tasks.code_solution:
#include <iostream>
using namespace std;

int main() {
    int n, contor = 0;
    cin >> n;

    for (int i = 1; i <= n; i++) {
        if (n % i == 0) contor++;
    }

    if (contor == 2) cout << "Prim";
    else cout << "Nu e prim";

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, maxCifra = 0;
    cin >> n;

    while (n > 0) {
        int cifra = n % 10;
        if (cifra > maxCifra) maxCifra = cifra;
        n = n / 10;
    }

    cout << "Cifra maxima: " << maxCifra;
    return 0;
}

